import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'Missing tenant token' });
  // In production this would verify JWT; here we decode payload
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userId = payload.sub;
    next();
  } catch (e) {
    res.status(401).json({ error: 'Invalid token' });
  }
}

// Search endpoint with dynamic filtering
app.get('/api/v2/documents/search', extractTenant, async (req, res) => {
  try {
    const { q, category, sort_by, order, limit } = req.query;

    let baseQuery = `SELECT id, title, content_preview, category, created_at, owner_id 
                     FROM documents WHERE tenant_id = $1`;
    const params = [req.tenantId];
    let paramIdx = 2;

    if (q) {
      baseQuery += ` AND (title ILIKE $${paramIdx} OR content_preview ILIKE $${paramIdx})`;
      params.push(`%${q}%`);
      paramIdx++;
    }

    if (category) {
      baseQuery += ` AND category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }

    // Dynamic sort - vulnerable to SQL injection
    const allowedColumns = ['title', 'created_at', 'category'];
    const sortColumn = sort_by || 'created_at';
    const sortOrder = order && order.toUpperCase() === 'ASC' ? 'ASC' : 'DESC';

    // Developer attempted validation but used includes() incorrectly
    // This checks if the input CONTAINS an allowed column name, not equality
    if (allowedColumns.some(col => sortColumn.includes(col))) {
      baseQuery += ` ORDER BY ${sortColumn} ${sortOrder}`;
    } else {
      baseQuery += ` ORDER BY created_at DESC`;
    }

    const resultLimit = Math.min(parseInt(limit) || 25, 100);
    baseQuery += ` LIMIT ${resultLimit}`;

    const result = await pool.query(baseQuery, params);

    // Audit log
    await pool.query(
      'INSERT INTO audit_log (tenant_id, user_id, action, details, ts) VALUES ($1, $2, $3, $4, NOW())',
      [req.tenantId, req.userId, 'document_search', JSON.stringify({ q, category, sort_by, results: result.rowCount })]
    );

    res.json({ documents: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Export documents endpoint
app.post('/api/v2/documents/export', extractTenant, async (req, res) => {
  const { document_ids, format } = req.body;
  if (!Array.isArray(document_ids) || document_ids.length === 0) {
    return res.status(400).json({ error: 'document_ids required' });
  }

  const placeholders = document_ids.map((_, i) => `$${i + 2}`).join(',');
  const query = `SELECT * FROM documents WHERE tenant_id = $1 AND id IN (${placeholders})`;
  const result = await pool.query(query, [req.tenantId, ...document_ids]);

  const exportId = crypto.randomUUID();
  res.json({ export_id: exportId, count: result.rowCount, format: format || 'json' });
});

app.listen(3000, () => console.log('Document service listening on :3000'));
